import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import {createStore,currentProfile,switchProfile,clearProfile,getPractice,practiceAttempt,finishPractice,select,advance,units,startTest,chooseTest,submitTest,testResults,retryWrong,loadStore,saveStore,STORE_KEY,testCursor,navigateTest} from '../dist/model.js';
const memory=()=>{const map=new Map();return {getItem:k=>map.get(k)??null,setItem:(k,v)=>map.set(k,v)};};
test('profiles isolate practice, mistakes, assessments and current selection',()=>{const s=createStore(),a=getPractice(s,'math');select(a,'3');practiceAttempt(s,a);startTest(s,'math');chooseTest(s,0,'5');assert.equal(currentProfile(s).wrongs.length,1);assert.equal(switchProfile(s,'invalid'),false);switchProfile(s,'B');assert.equal(currentProfile(s).wrongs.length,0);assert.equal(currentProfile(s).activeTest,null);assert.equal(getPractice(s,'math').records[0].attempts,0);switchProfile(s,'A');assert.equal(getPractice(s,'math').records[0].attempts,1);assert.equal(currentProfile(s).activeTest.answers[0],'5');});
test('mistakes retain original answer/date and track retry correction without deletion',()=>{const s=createStore(),a=getPractice(s,'math');select(a,'3');assert.equal(practiceAttempt(s,a),true);const r=currentProfile(s).wrongs[0],original=JSON.stringify({chosen:r.chosen,date:r.date,expected:r.expected});assert.equal(r.correctedAt,null);assert.equal(retryWrong(s,r.id,'9'),false);assert.equal(retryWrong(s,r.id,'invalid'),null);assert.equal(retryWrong(s,r.id,'4'),true);assert.ok(r.correctedAt);assert.equal(r.retries.length,2);assert.equal(currentProfile(s).wrongs.length,1);assert.equal(JSON.stringify({chosen:r.chosen,date:r.date,expected:r.expected}),original);switchProfile(s,'B');assert.equal(retryWrong(s,r.id,'4'),null);});
test('skip is recorded separately, later practice success preserves original wrong',()=>{const s=createStore(),a=getPractice(s,'math');practiceAttempt(s,a,true);assert.equal(currentProfile(s).wrongs[0].chosen,null);select(a,'4');practiceAttempt(s,a);assert.equal(currentProfile(s).wrongs.length,1);assert.equal(a.records[0].firstCorrect,false);assert.equal(currentProfile(s).wrongs[0].correctedAt,null);});
for(const subject of Object.keys(units))test(`${subject} assessment gates results, checks answers, routes wrongs and deduplicates completion`,()=>{const s=createStore(),t=startTest(s,subject);assert.equal(t.answers.length,4);assert.equal(new Set(units[subject].items.map(q=>q.question)).size,4);assert.equal(submitTest(s),false);assert.equal(testResults(t),null);assert.equal(chooseTest(s,0,'invalid'),false);units[subject].items.forEach((q,i)=>chooseTest(s,i,i===0?q.choices.find(c=>c!==q.answer):q.answer));assert.equal(testResults(t),null);assert.equal(submitTest(s),true);assert.equal(testResults(t).filter(r=>r.correct).length,3);assert.equal(currentProfile(s).wrongs.length,1);assert.equal(currentProfile(s).wrongs[0].source,'单元测评');assert.equal(currentProfile(s).assessments.length,1);assert.equal(submitTest(s),false);assert.equal(chooseTest(s,0,units[subject].items[0].answer),false);assert.equal(currentProfile(s).assessments.length,1);const next=startTest(s,subject);assert.notEqual(next.id,t.id);assert.equal(testResults(next),null);assert.equal(currentProfile(s).assessments.length,1);});
test('practice completion deduplicates, explicit restart creates a fresh run',()=>{const s=createStore(),a=getPractice(s,'math');assert.equal(finishPractice(s,a),false);select(a,'4');practiceAttempt(s,a);advance(a);select(a,'6');practiceAttempt(s,a);advance(a);assert.equal(finishPractice(s,a),true);assert.equal(finishPractice(s,a),false);assert.equal(currentProfile(s).practiceCompleted.length,1);assert.equal(getPractice(s,'math').id,a.id);assert.notEqual(getPractice(s,'math',true).id,a.id);assert.equal(currentProfile(s).practiceCompleted.length,1);});
test('storage restores in-progress practice, test selection and wrong retry history',()=>{const storage=memory(),s=createStore(),a=getPractice(s,'math');select(a,'3');practiceAttempt(s,a);retryWrong(s,currentProfile(s).wrongs[0].id,'4');startTest(s,'english');chooseTest(s,2,'an');switchProfile(s,'B');assert.equal(saveStore(storage,s),'');const result=loadStore(storage);assert.equal(result.warning,'');assert.deepEqual(result.store,s);switchProfile(result.store,'A');assert.equal(getPractice(result.store,'math').feedback,'try');assert.equal(currentProfile(result.store).activeTest.answers[2],'an');assert.ok(currentProfile(result.store).wrongs[0].correctedAt);});
test('completed assessment survives restore and cannot count twice after refresh',()=>{const storage=memory(),s=createStore();startTest(s,'chinese');units.chinese.items.forEach((q,i)=>chooseTest(s,i,q.answer));submitTest(s);saveStore(storage,s);const restored=loadStore(storage).store;assert.equal(testResults(currentProfile(restored).activeTest).length,4);assert.equal(submitTest(restored),false);assert.equal(currentProfile(restored).assessments.length,1);});
test('corrupt, malformed and future-version storage safely starts blank with a warning',()=>{for(const raw of ['{broken',JSON.stringify({version:2}),JSON.stringify({...createStore(),profiles:{A:null,B:{}}}),JSON.stringify({...createStore(),profiles:{...createStore().profiles,A:{...createStore().profiles.A,wrongs:[{}]}}})]){const storage=memory();storage.setItem(STORE_KEY,raw);const result=loadStore(storage);assert.ok(result.warning);assert.deepEqual(result.store,createStore());assert.equal(storage.getItem(STORE_KEY),raw);}});
test('unavailable storage and quota errors are visible instead of crashing',()=>{const blocked={getItem(){throw Error('denied')},setItem(){throw Error('quota')}};assert.ok(loadStore(blocked).warning);assert.ok(saveStore(blocked,createStore()));assert.ok(loadStore(null).warning);assert.ok(saveStore(null,createStore()));});
test('clear removes only current profile and persists removal',()=>{const s=createStore(),storage=memory();let a=getPractice(s,'math');practiceAttempt(s,a,true);switchProfile(s,'B');startTest(s,'english');const before=structuredClone(currentProfile(s));switchProfile(s,'A');clearProfile(s);assert.deepEqual(currentProfile(s),createStore().profiles.A);assert.deepEqual(s.profiles.B,before);saveStore(storage,s);assert.deepEqual(loadStore(storage).store,s);});
test('UI includes explicit local/privacy labels, confirmation, native video and no active voice capture',()=>{const html=fs.readFileSync(new URL('../dist/index.html',import.meta.url),'utf8'),app=fs.readFileSync(new URL('../dist/app.js',import.meta.url),'utf8');assert.match(html,/id="clear-confirm"/);assert.match(html,/id="replace-test"/);assert.match(app,/记录只保存在此浏览器/);assert.match(app,/不是账号或身份验证/);assert.match(app,/controls playsinline preload="metadata"/);assert.match(app,/\/media\/average-sharing.mp4/);assert.match(app,/\/media\/average-sharing-poster.jpg/);assert.match(app,/不会向服务商发送提问/);assert.doesNotMatch(app,/autoplay|getUserMedia|SpeechRecognition/);});

test('non-object and array practice containers are rejected before restoration',()=>{for(const practices of [1,[],null,'bad',true]){const storage=memory(),s=createStore();s.profiles.A.practices=practices;storage.setItem(STORE_KEY,JSON.stringify(s));const loaded=loadStore(storage);assert.ok(loaded.warning);assert.deepEqual(loaded.store,createStore());assert.doesNotThrow(()=>getPractice(loaded.store,'math'));}});


test('assessment navigation saves the current question without changing answers or allowing early submission',()=>{const storage=memory(),s=createStore(),t=startTest(s,'math');assert.equal(testCursor(t),0);chooseTest(s,0,'5');assert.equal(navigateTest(s,2),true);assert.equal(testCursor(t),2);assert.deepEqual(t.answers,['5',null,null,null]);assert.equal(submitTest(s),false);saveStore(storage,s);const restored=loadStore(storage).store;assert.equal(testCursor(currentProfile(restored).activeTest),2);for(const invalid of [-1,4,NaN,1.5])assert.equal(navigateTest(s,invalid),false);units.math.items.forEach((q,i)=>chooseTest(s,i,q.answer));submitTest(s);assert.equal(navigateTest(s,0),false);assert.equal(testResults(t).length,4);});
test('older saved assessments without a cursor resume at the first unanswered question',()=>{const storage=memory(),s=createStore(),t=startTest(s,'english');delete t.cursor;chooseTest(s,0,'a');chooseTest(s,2,'an');saveStore(storage,s);const loaded=loadStore(storage);assert.equal(loaded.warning,'');assert.equal(testCursor(currentProfile(loaded.store).activeTest),1);});
test('invalid saved assessment cursor is rejected instead of rendering a missing question',()=>{for(const cursor of [-1,4,'1',null]){const storage=memory(),s=createStore();startTest(s,'math').cursor=cursor;saveStore(storage,s);assert.ok(loadStore(storage).warning);}});
